True from collections import Counter

def _runs(indices):
    if not indices:
        return []
    groups = [[indices[0]]]
    for x in indices[1:]:
        if x == groups[-1][-1] + 1:
            groups[-1].append(x)
        else:
            groups.append([x])
    return groups

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    border_candidates = Counter(v for v in set(sum(grid, [])) if v != bg)
    # Border color is the non-background color most often touching the outer edge.
    edge = grid[0] + grid[-1] + [grid[r][0] for r in range(h)] + [grid[r][-1] for r in range(h)]
    border = Counter(v for v in edge if v != bg).most_common(1)[0][0]
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,border)]
    if not markers:
        return out
    ink = grid[markers[0][0]][markers[0][1]]

    # Find matching uninterrupted border segments on opposite sides.
    for side_a, side_b, span in [('left','right',h), ('top','bottom',w)]:
        if side_a == 'left':
            aidx = [r for r in range(h) if grid[r][0] == border]
            bidx = [r for r in range(h) if grid[r][w-1] == border]
        else:
            aidx = [c for c in range(w) if grid[0][c] == border]
            bidx = [c for c in range(w) if grid[h-1][c] == border]
        aruns, bruns = _runs(aidx), _runs(bidx)
        for ar in aruns:
            for br in bruns:
                if len(ar) != len(br):
                    continue
                # Markers can lie in either stripe. A matching offset launches a full line
                # across the opposite stripe, while the marker itself rays to its border.
                for r,c in markers:
                    pos = r if side_a == 'left' else c
                    if pos in ar:
                        origin, dest = ar, br
                        nearer = side_a
                    elif pos in br:
                        origin, dest = br, ar
                        nearer = side_b
                    else:
                        continue
                    off = pos - origin[0]
                    target = dest[0] + off
                    if side_a == 'left':
                        # Complete corresponding row in the opposite border stripe.
                        for cc in range(w):
                            if out[target][cc] != border:
                                out[target][cc] = ink
                        # Draw from marker toward the border on its own stripe.
                        if nearer == 'left':
                            for cc in range(1,c):
                                if grid[r][cc] == bg: out[r][cc] = ink
                        else:
                            for cc in range(c+1,w-1):
                                if grid[r][cc] == bg: out[r][cc] = ink
                    else:
                        for rr in range(h):
                            if out[rr][target] != border:
                                out[rr][target] = ink
                        if nearer == 'top':
                            for rr in range(1,r):
                                if grid[rr][c] == bg: out[rr][c] = ink
                        else:
                            for rr in range(r+1,h-1):
                                if grid[rr][c] == bg: out[rr][c] = ink
                    out[r][c] = 4
                return out
    for r,c in markers:
        out[r][c] = 4
    return out
